import{_ as a,o as i,c as e,aO as n}from"./chunks/framework.vjUPZZJn.js";const k=JSON.parse('{"title":"Linux 定时任务：cron 与 systemd timer","description":"","frontmatter":{"date":"2026-09-15T11:30:00.000Z","title":"Linux 定时任务：cron 与 systemd timer","source":[["1-知识/工具/Linux环境/Linux 定时任务：cron 与 systemd timer"]],"tags":["工具","教程手册","Linux","systemd","定时任务"],"categories":["工具"],"permalink":"/pages/2a0407"},"headers":[],"relativePath":"工具/Linux 定时任务：cron 与 systemd timer.md","filePath":"工具/Linux 定时任务：cron 与 systemd timer.md","lastUpdated":1789441461000}'),t={name:"工具/Linux 定时任务：cron 与 systemd timer.md"};function l(r,s,p,d,h,o){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="linux-定时任务-cron-与-systemd-timer" tabindex="-1">Linux 定时任务：cron 与 systemd timer <a class="header-anchor" href="#linux-定时任务-cron-与-systemd-timer" aria-label="Permalink to &quot;Linux 定时任务：cron 与 systemd timer&quot;">​</a></h1> <p>以「每天凌晨 5 点定时重启」为例，对比 Linux 下两种定时任务的配置方法：crontab 简单直接，是大多数日常场景的首选；systemd timer 步骤稍多，但更结构化，适合与系统服务深度集成的任务。读完可以直接照抄两种配置，并知道什么场景选哪个。已部署任务的完整移除流程见 <a href="./systemd 定时任务与服务清理.html">systemd 定时任务与服务清理</a>。</p> <h2 id="方法一-crontab-推荐-最常用" tabindex="-1">方法一：crontab（推荐，最常用） <a class="header-anchor" href="#方法一-crontab-推荐-最常用" aria-label="Permalink to &quot;方法一：crontab（推荐，最常用）&quot;">​</a></h2> <ol><li>编辑 root 用户的 crontab（重启需要 root 权限）：</li></ol> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crontab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>第一次操作时会让你选择默认编辑器。</p> <ol start="2"><li>在文件末尾添加一行：</li></ol> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 5 * * * /sbin/reboot</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>0 5 * * *</code>：五个字段依次为 分 时 日 月 周，即每天凌晨 5 点整</li> <li><code>/sbin/reboot</code>：要执行的命令，写绝对路径</li></ul> <ol start="3"><li><p>保存退出：vim 按 <code>Esc</code> 后输入 <code>:wq</code> 回车；nano 按 <code>Ctrl+X</code>，按 <code>Y</code> 确认，回车保存。</p></li> <li><p>验证任务已添加：</p></li></ol> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crontab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="方法二-systemd-timer" tabindex="-1">方法二：systemd timer <a class="header-anchor" href="#方法二-systemd-timer" aria-label="Permalink to &quot;方法二：systemd timer&quot;">​</a></h2> <ol><li>创建 service 文件 <code>/etc/systemd/system/daily-reboot.service</code>，定义「执行什么」：</li></ol> <div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Daily Reboot</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=oneshot</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/usr/sbin/reboot</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><code>Type=oneshot</code> 表示一次性任务，执行完即退出。</p> <ol start="2"><li>创建同名 timer 文件 <code>/etc/systemd/system/daily-reboot.timer</code>，定义「何时执行」：</li></ol> <div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Triggers a daily reboot at 5:00 AM</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Timer]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">OnCalendar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=*-*-* 05:00:00</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Persistent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WantedBy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=timers.target</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><ul><li><code>OnCalendar=*-*-* 05:00:00</code>：年-月-日 05:00:00，即每天凌晨 5 点</li> <li><code>Persistent=true</code>：若触发时刻系统处于关机状态，下次开机后立即补执行一次</li></ul> <ol start="3"><li>启用并启动 timer：</li></ol> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 重新加载 systemd 配置，使其识别新文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启用（开机自动激活）并启动</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daily-reboot.timer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daily-reboot.timer</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ol start="4"><li>验证：</li></ol> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daily-reboot.timer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-timers</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>日历表达式可用 <code>systemd-analyze calendar &quot;*-*-* 05:00:00&quot;</code> 验证，会输出规范化形式和下次触发时间。</p> <h2 id="方法对比" tabindex="-1">方法对比 <a class="header-anchor" href="#方法对比" aria-label="Permalink to &quot;方法对比&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>特性</th> <th>crontab</th> <th>systemd timer</th></tr></thead> <tbody><tr><td>简单性</td> <td>一行配置</td> <td>需创建 service + timer 两个文件</td></tr> <tr><td>日志</td> <td><code>/var/log/syslog</code> 或 journalctl</td> <td><code>journalctl -u xxx.service</code>，更清晰</td></tr> <tr><td>灵活性</td> <td>时间语法成熟灵活</td> <td>同样强大，另支持单调定时器（相对启动时间）</td></tr> <tr><td>依赖管理</td> <td>弱</td> <td>强，可定义与其他服务的依赖关系</td></tr> <tr><td>适用场景</td> <td>绝大多数日常自动化任务</td> <td>与系统服务深度集成的复杂任务</td></tr></tbody></table> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>一行搞定、与系统服务无关的任务用 crontab；需要依赖管理、精确日志、错过的触发补执行（<code>Persistent=true</code>）时用 systemd timer</li> <li>systemd timer 的 service 与 timer 必须同名，<code>daemon-reload</code> 不可省</li> <li>日历表达式拿不准时，先用 <code>systemd-analyze calendar</code> 验证再写入配置</li></ul>`,46)])])}const b=a(t,[["render",l]]);export{k as __pageData,b as default};
